import {test,expect,vi} from 'vitest';
import {env,runInDurableObject,runDurableObjectAlarm,abortAllDurableObjects,SELF} from 'cloudflare:test';
import cbor from 'cbor';
import * as pki from 'pkijs';
import fixtures from 'djc-assertion-state-fixtures';
import {ReceiptKeyStore} from './receipt-key-store';
const namespace=env.ASSERTION_KEY_STATE,decode=v=>Uint8Array.from(atob(v),c=>c.charCodeAt(0)),u=v=>Buffer.from(v).toString('base64url'),text=v=>new TextEncoder().encode(v);
const hash=async v=>new Uint8Array(await crypto.subtle.digest('SHA-256',v)),hex=v=>Buffer.from(v).toString('hex');
const join=(a,b)=>Uint8Array.from([...a,...b]);
const stub=()=>namespace.get(namespace.idFromName(crypto.randomUUID()));
const clock=async(at,body)=>{vi.useFakeTimers({toFake:['Date']});vi.setSystemTime(at);try{await body();}finally{vi.useRealTimers();}};
const row=s=>runInDurableObject(s,(_i,state)=>state.storage.sql.exec('SELECT value FROM key_state').toArray().map(v=>JSON.parse(v.value))[0]);
const ops=s=>runInDurableObject(s,(_i,state)=>state.storage.sql.exec('SELECT value FROM proof_operations').toArray().map(v=>JSON.parse(v.value)));
const denied=async p=>expect(await p).toMatchObject({ok:false});
async function software(){const keys=await crypto.subtle.generateKey({name:'ECDSA',namedCurve:'P-256'},false,['sign','verify']),point=new Uint8Array(await crypto.subtle.exportKey('raw',keys.publicKey));return {keys,point,keyId:btoa(String.fromCharCode(...await hash(point)))};}
async function setup(f,install=true){
 const s=stub();await runInDurableObject(s,i=>{i.env.RECEIPT_ACTIVE_KEY=btoa(String.fromCharCode(...new Uint8Array(32).fill(11)));i.env.ASSERTION_POLICY_ENABLED='ios-dev-qualification/1';i.env.ASSERTION_POLICY_EXPIRES_AT=String(Date.now()+1e9);});
 const keyAddress=hex(await hash(text(JSON.stringify(['development','ios-dev-qualification/1',f.keyId])))),originalNow=Date.now();
 const m={keyAddress,appPolicy:'ios-dev-qualification/1',environment:'development',publicPoint:btoa(String.fromCharCode(...f.point)),receipt:btoa('PUBLIC_SYNTHETIC_TRUSTED_STORAGE_SEED_NOT_ENROLLMENT'),receiptCreatedAt:originalNow-1000,challengeCreatedAt:originalNow-1000,challengeExpiresAt:originalNow+119000,operationId:crypto.randomUUID(),requestDigest:'b'.repeat(64)};
 if(install)expect((await runInDurableObject(s,i=>ReceiptKeyStore.prototype.install.call(i,m))).ok).toBe(true);return {s,m};
}
test('trusted storage fixture retains one original clock sample across a millisecond boundary',async()=>{
 const f=await software(),started=Date.now();let ticks=0;
 const timer=vi.spyOn(Date,'now').mockImplementation(()=>started+ticks++);
 try{
  const {m}=await setup(f);
  expect(m.challengeExpiresAt-m.challengeCreatedAt).toBe(120000);
  expect(m.receiptCreatedAt).toBe(m.challengeCreatedAt);
  const s=stub(),overlong={...m,challengeExpiresAt:m.challengeExpiresAt+1};
  expect(await runInDurableObject(s,i=>ReceiptKeyStore.prototype.install.call(i,overlong))).toEqual({ok:false,error:'store_rejected'});
 }finally{timer.mockRestore();}
});
const issue=(s,f,action='recover-key',binding)=>s.issue({action,keyId:f.keyId,...(binding?{binding}:{})});
const binding=()=>({transactionId:crypto.randomUUID(),generation:1,browserThumbprint:u(new Uint8Array(32).fill(1)),envelopeDigest:u(new Uint8Array(32).fill(2)),expiresAt:Date.now()+120000});
async function proof(f,ch,counter=1,action='recover-key'){
 let auth=new Uint8Array(37);auth.set(await hash(text('ZEML4LPXH4.dev.djconnect.ios')));auth[32]=0xc0;new DataView(auth.buffer).setUint32(33,counter,false);
 auth=join(auth,new Uint8Array(cbor.encode(new Map([['apple_bundle_version_01','40230'],['apple_validation_category_01',Buffer.from([3,0,0,0])]]))));
 const nonce=await hash(join(auth,await hash(Buffer.from(ch.client_data,'base64url'))));
 const signature=pki.createCMSECDSASignature(await crypto.subtle.sign({name:'ECDSA',hash:'SHA-256'},f.keys.privateKey,nonce));
 return {operationId:ch.challenge_id,action,clientData:ch.client_data,assertion:u(cbor.encode(new Map([['signature',Buffer.from(signature)],['authenticatorData',Buffer.from(auth)]])))};
}
test('all public requests remain unavailable and unverified helper RPCs denied',async()=>{const f=await software(),{s,m}=await setup(f);expect((await SELF.fetch('https://example.test/v1/rendezvous/submit',{method:'POST'})).status).toBe(503);await denied(s.install(m));await denied(s.advance(999));await denied(s.evidence());});
test('recover uses exact saved wire bytes then atomically removes nonce and commits counter/receipt',async()=>{
 const f=await software(),{s}=await setup(f),ch=await issue(s,f);expect(ch.ok).toBe(true);expect(Buffer.from(ch.challenge_id,'base64url').length).toBe(32);
 const body=JSON.parse(Buffer.from(ch.client_data,'base64url'));expect(body).toEqual({v:'djc-rendezvous/1',action:'recover-key',service_origin:'https://api.djconnect.dev',key_id:f.keyId,challenge_id:ch.challenge_id,challenge:ch.challenge,expires_at:ch.expires_at});
 const request=await proof(f,ch),before=await row(s),result=await s.authorize(request);expect(result).toMatchObject({ok:true,kind:'recovery-receipt',counter:1,keyExpiresAt:before.expiresAt});
 expect((await row(s)).counter).toBe(1);const receipt=(await ops(s))[0];expect(receipt.status).toBe('authorized');for(const name of ['clientData','nonce','assertion','proof'])expect(receipt[name]).toBeUndefined();expect(JSON.stringify(receipt)).not.toContain(request.assertion);
 expect(await s.authorize(request)).toEqual(result);expect((await row(s)).counter).toBe(1);expect((await row(s)).expiresAt).toBe(before.expiresAt);
});
for(const known of [false,true])test('management challenge coalesces without renewal, known='+known,async()=>{
 const f=await software(),{s}=await setup(f,known),first=await issue(s,f);await clock(first.expires_at-1,async()=>{expect(await issue(s,f)).toEqual(first);});expect((await ops(s)).length).toBe(1);
 const other=await issue(s,f,'delete-key');expect(other.challenge_id).not.toBe(first.challenge_id);expect((await ops(s)).length).toBe(2);
});
test('concurrent management issuance stores one challenge',async()=>{const f=await software(),{s}=await setup(f,false),results=await Promise.all(Array.from({length:8},()=>issue(s,f)));expect(results.every(v=>v.ok)).toBe(true);expect(new Set(results.map(v=>v.challenge_id)).size).toBe(1);expect((await ops(s)).length).toBe(1);});
test('random-ID collision cannot overwrite an existing challenge',async()=>{const f=await software(),{s}=await setup(f,false),first=await issue(s,f),before=await ops(s);await runInDurableObject(s,async(i)=>{const id=Buffer.from(first.challenge_id,'base64url'),spy=vi.spyOn(crypto,'getRandomValues').mockImplementation(target=>{new Uint8Array(target.buffer,target.byteOffset,target.byteLength).set(id);return target;});try{expect((await i.issue({action:'delete-key',keyId:f.keyId})).ok).toBe(false);}finally{spy.mockRestore();}});expect(await ops(s)).toEqual(before);});
test('unknown key cannot authorize or allocate a key through recovery',async()=>{const f=await software(),{s}=await setup(f,false),ch=await issue(s,f);await denied(s.authorize(await proof(f,ch)));expect(await row(s)).toBeUndefined();});
test('28-submit bound preserves management capacity and cleanup permits a new bounded attempt',async()=>{const f=await software(),{s}=await setup(f,false);let deadline;for(let n=0;n<28;n++){const ch=await issue(s,f,'submit',binding());expect(ch.ok).toBe(true);deadline=Math.max(deadline??0,ch.expires_at);}await denied(issue(s,f,'submit',binding()));expect((await issue(s,f)).ok).toBe(true);expect((await issue(s,f,'delete-key')).ok).toBe(true);expect((await ops(s)).length).toBe(30);deadline=Math.max(...(await ops(s)).map(op=>op.expiresAt));await clock(deadline,async()=>{expect((await issue(s,f)).ok).toBe(true);expect((await ops(s)).length).toBe(1);});});
test('unknown management cleanup alarm removes state without client retry',async()=>{const f=await software(),{s}=await setup(f,false),ch=await issue(s,f);await clock(ch.expires_at,async()=>{expect(await runDurableObjectAlarm(s)).toBe(true);expect(await ops(s)).toEqual([]);expect(await runInDurableObject(s,(_i,state)=>state.storage.getAlarm())).toBeNull();});});
test('failed precommit alarm creates no challenge',async()=>{const f=await software(),{s}=await setup(f,false);await runInDurableObject(s,async(i,state)=>{const spy=vi.spyOn(state.storage,'setAlarm').mockRejectedValueOnce(new Error('qa_alarm_fault'));try{expect(await i.issue({action:'recover-key',keyId:f.keyId})).toEqual({ok:false,error:'service_unavailable'});expect(spy).toHaveBeenCalledTimes(1);}finally{spy.mockRestore();}});expect(await ops(s)).toEqual([]);});
for(const kind of ['clientData','action','operation','proof'])test('invalid proof request preserves nonce/counter: '+kind,async()=>{const f=await software(),{s}=await setup(f),ch=await issue(s,f),request=await proof(f,ch),bad={...request};if(kind==='clientData')bad.clientData=u(text('changed'));if(kind==='action')bad.action='delete-key';if(kind==='operation')bad.operationId=u(crypto.getRandomValues(new Uint8Array(32)));if(kind==='proof'){const b=Buffer.from(bad.assertion,'base64url');b[10]^=1;bad.assertion=u(b);}await denied(s.authorize(bad));expect((await row(s)).counter).toBe(0);expect((await ops(s))[0].status).toBe('challenge');expect((await s.authorize(request)).ok).toBe(true);});
test('changed valid signature for same operation conflicts with original immutable receipt',async()=>{const f=await software(),{s}=await setup(f),ch=await issue(s,f),request=await proof(f,ch);expect((await s.authorize(request)).ok).toBe(true);await denied(s.authorize(await proof(f,ch)));expect((await row(s)).counter).toBe(1);});
test('parallel same proof advances once; exact retry recovers original receipt',async()=>{const f=await software(),{s}=await setup(f),request=await proof(f,await issue(s,f)),results=await Promise.all(Array.from({length:8},()=>s.authorize(request)));expect(results.some(v=>v.ok)).toBe(true);expect((await row(s)).counter).toBe(1);expect((await ops(s)).filter(v=>v.status==='authorized').length).toBe(1);expect((await s.authorize(request)).ok).toBe(true);});
test('one key across two operations never lowers highest counter',async()=>{const f=await software(),{s}=await setup(f),a=await issue(s,f,'submit',binding()),b=await issue(s,f),high=await proof(f,a,4,'submit'),low=await proof(f,b,2);expect((await s.authorize(high)).ok).toBe(true);await denied(s.authorize(low));expect((await row(s)).counter).toBe(4);});
test('unsigned maximum counter never wraps',async()=>{const f=await software(),{s}=await setup(f),ch=await issue(s,f);expect((await s.authorize(await proof(f,ch,0xffffffff))).ok).toBe(true);const next=await issue(s,f);await denied(s.authorize(await proof(f,next,1)));expect((await row(s)).counter).toBe(0xffffffff);});
test('submit clientData and immutable lease bind exact authoritative internal tuple',async()=>{const f=await software(),{s}=await setup(f),b=binding(),ch=await issue(s,f,'submit',b),body=JSON.parse(Buffer.from(ch.client_data,'base64url'));expect(body).toMatchObject({action:'submit',transaction_id:b.transactionId,generation:b.generation,browser_key_thumbprint:b.browserThumbprint,envelope_digest:b.envelopeDigest,expires_at:b.expiresAt});const request=await proof(f,ch,1,'submit'),result=await s.authorize(request);expect(result).toMatchObject({ok:true,kind:'submit-authorization',counter:1,binding:b});expect(result.authorizationExpiresAt<=Date.now()+5000).toBe(true);expect(await s.lookupSubmit(result.operationId,result.requestDigest)).toEqual(result);await denied(s.lookupSubmit(result.operationId,'a'.repeat(64)));await clock(result.authorizationExpiresAt,async()=>{await denied(s.authorize(request));await denied(s.lookupSubmit(result.operationId,result.requestDigest));expect((await row(s)).counter).toBe(1);});});
test('lost submit response retry retains original five-second deadline',async()=>{const f=await software(),{s}=await setup(f),ch=await issue(s,f,'submit',binding()),request=await proof(f,ch,1,'submit'),first=await s.authorize(request);await clock(first.authorizationExpiresAt-1,async()=>{expect(await s.authorize(request)).toEqual(first);});expect((await row(s)).counter).toBe(1);});
test('postcommit alarm failure burns counter and retry recovers only original lease',async()=>{
 const f=await software(),{s}=await setup(f),ch=await issue(s,f,'submit',binding()),request=await proof(f,ch,1,'submit');
 await runInDurableObject(s,async(i,state)=>{const spy=vi.spyOn(state.storage,'setAlarm').mockRejectedValueOnce(new Error('qa_postcommit_alarm_fault'));try{expect(await i.authorize(request)).toEqual({ok:false,error:'service_unavailable'});expect(spy).toHaveBeenCalledTimes(1);}finally{spy.mockRestore();}});
 const saved=(await ops(s))[0];expect(saved.status).toBe('authorized');expect((await row(s)).counter).toBe(1);
 const result=await s.authorize(request);expect(result.ok).toBe(true);expect(result.authorizationExpiresAt).toBe(saved.authorizationExpiresAt);expect((await row(s)).counter).toBe(1);
 await clock(saved.authorizationExpiresAt,async()=>{await denied(s.authorize(request));});
});
test('known policy deadline caps lease',async()=>{const f=await software(),{s}=await setup(f),ch=await issue(s,f,'submit',binding()),request=await proof(f,ch,1,'submit'),until=Date.now()+3000;await runInDurableObject(s,i=>{i.env.ASSERTION_POLICY_EXPIRES_AT=String(until);});const result=await s.authorize(request);expect(result.ok).toBe(true);expect(result.authorizationExpiresAt).toBe(until);});
test('original transaction and key deadline cap lease',async()=>{const f=await software(),{s}=await setup(f),b={...binding(),expiresAt:Date.now()+3000},ch=await issue(s,f,'submit',b);await runInDurableObject(s,(_i,state)=>{const r=JSON.parse(state.storage.sql.exec('SELECT value FROM key_state').toArray()[0].value);r.expiresAt=b.expiresAt-1000;state.storage.sql.exec('UPDATE key_state SET value=?',JSON.stringify(r));});const result=await s.authorize(await proof(f,ch,1,'submit'));expect(result.ok).toBe(true);expect(result.authorizationExpiresAt).toBe(b.expiresAt-1000);});
test('challenge expiry equality denies even before alarm',async()=>{const f=await software(),{s}=await setup(f),ch=await issue(s,f),request=await proof(f,ch);await clock(ch.expires_at,async()=>{await denied(s.authorize(request));expect((await row(s)).counter).toBe(0);});});
test('SQL receipt fault rolls back counter and nonce; same proof succeeds after repair',async()=>{const f=await software(),{s}=await setup(f),ch=await issue(s,f),request=await proof(f,ch);await runInDurableObject(s,(_i,state)=>state.storage.sql.exec("CREATE TRIGGER qa_receipt_fault BEFORE UPDATE ON proof_operations WHEN json_extract(NEW.value,'$.status')='authorized' BEGIN SELECT RAISE(ABORT,'qa_fault'); END"));expect(await s.authorize(request)).toEqual({ok:false,error:'service_unavailable'});expect((await row(s)).counter).toBe(0);expect((await ops(s))[0].status).toBe('challenge');await runInDurableObject(s,(_i,state)=>state.storage.sql.exec('DROP TRIGGER qa_receipt_fault'));expect((await s.authorize(request)).ok).toBe(true);});
for(const mutation of ['revoke','expiry','policy','point','counter'])test('post-crypto recheck denies intervening '+mutation,async()=>{
 const f=await software(),{s}=await setup(f),ch=await issue(s,f),request=await proof(f,ch);
 await runInDurableObject(s,async(i,state)=>{const original=crypto.subtle.verify.bind(crypto.subtle);let first=true;const spy=vi.spyOn(crypto.subtle,'verify').mockImplementation(async(...args)=>{const valid=await original(...args);if(first){first=false;if(mutation==='revoke')await i.revoke();else if(mutation==='policy')i.env.ASSERTION_POLICY_ENABLED='disabled';else{const r=JSON.parse(state.storage.sql.exec('SELECT value FROM key_state').toArray()[0].value);if(mutation==='expiry')r.expiresAt=Date.now();if(mutation==='point')r.publicPoint=btoa(String.fromCharCode(4,...new Uint8Array(64).fill(2)));if(mutation==='counter')r.counter=2;state.storage.sql.exec('UPDATE key_state SET value=?',JSON.stringify(r));}}return valid;});try{expect((await i.authorize(request)).ok).toBe(false);}finally{spy.mockRestore();}});
 if(mutation!=='revoke')expect((await row(s)).counter).toBe(mutation==='counter'?2:0);
});
test('authenticated deletion erases key evidence and every operation atomically',async()=>{const f=await software(),{s}=await setup(f),recover=await issue(s,f),del=await issue(s,f,'delete-key'),request=await proof(f,del,1,'delete-key');expect((await s.authorize(request)).kind).toBe('deleted');const r=await row(s);expect(r.status).toBe('revoked');for(const name of ['publicPoint','counter','ciphertext','nonce'])expect(r[name]).toBeUndefined();expect(await ops(s)).toEqual([]);await denied(s.authorize(request));await denied(s.authorize(await proof(f,recover,2)));});
test('deletion SQL fault preserves key and challenges until repaired',async()=>{const f=await software(),{s}=await setup(f),ch=await issue(s,f,'delete-key'),request=await proof(f,ch,1,'delete-key');await runInDurableObject(s,(_i,state)=>state.storage.sql.exec("CREATE TRIGGER qa_delete_fault BEFORE DELETE ON proof_operations BEGIN SELECT RAISE(ABORT,'qa_fault'); END"));expect(await s.authorize(request)).toEqual({ok:false,error:'service_unavailable'});expect((await row(s)).status).toBe('active');expect((await ops(s)).length).toBe(1);await runInDurableObject(s,(_i,state)=>state.storage.sql.exec('DROP TRIGGER qa_delete_fault'));expect((await s.authorize(request)).kind).toBe('deleted');});
test('revoke wins over cached recovery receipt and submit lookup',async()=>{const f=await software(),{s}=await setup(f),a=await issue(s,f),request=await proof(f,a);expect((await s.authorize(request)).ok).toBe(true);const b=await issue(s,f,'submit',binding()),grant=await s.authorize(await proof(f,b,2,'submit'));await s.revoke();await denied(s.authorize(request));await denied(s.lookupSubmit(grant.operationId,grant.requestDigest));expect(await ops(s)).toEqual([]);});
test('local instance restart preserves encrypted key, counter and original operation receipt',async()=>{const f=await software(),{s}=await setup(f),request=await proof(f,await issue(s,f)),first=await s.authorize(request);const settings=await runInDurableObject(s,i=>({RECEIPT_ACTIVE_KEY:i.env.RECEIPT_ACTIVE_KEY,ASSERTION_POLICY_ENABLED:i.env.ASSERTION_POLICY_ENABLED,ASSERTION_POLICY_EXPIRES_AT:i.env.ASSERTION_POLICY_EXPIRES_AT}));await abortAllDurableObjects();const reopened=namespace.get(s.id);await runInDurableObject(reopened,i=>{Object.assign(i.env,settings);});expect(await reopened.authorize(request)).toEqual(first);expect((await row(reopened)).counter).toBe(1);});
for(const f of fixtures.genuine)test('genuine diagnostic signature plus atomic state, not native wire action: '+f.name,async()=>{
 const actual={point:decode(f.point),keyId:f.credential}, {s}=await setup(actual);const first=f.assertions[0],ch=await issue(s,actual),client=u(decode(first.input));
 await runInDurableObject(s,(_i,state)=>{const op=JSON.parse(state.storage.sql.exec('SELECT value FROM proof_operations WHERE id=?',ch.challenge_id).toArray()[0].value);op.clientData=client;state.storage.sql.exec('UPDATE proof_operations SET value=? WHERE id=?',JSON.stringify(op),ch.challenge_id);});
 const request={operationId:ch.challenge_id,action:'recover-key',clientData:client,assertion:u(decode(first.proof))},result=await s.authorize(request);expect(result).toMatchObject({ok:true,counter:first.counter});expect(await s.authorize(request)).toEqual(result);expect((await row(s)).counter).toBe(first.counter);
});

for(const phase of ['get-alarm','read','transaction','write','digest','random'])test('issue internal fault is unavailable with reached phase and explicit repair: '+phase,async()=>{const f=await software(),{s}=await setup(f,false);await runInDurableObject(s,async(i,c)=>{let hits=0;const target=phase==='read'||phase==='write'?c.storage.sql:phase==='transaction'||phase==='get-alarm'?c.storage:phase==='digest'?crypto.subtle:crypto,method=phase==='read'||phase==='write'?'exec':phase==='transaction'?'transactionSync':phase==='get-alarm'?'getAlarm':phase==='digest'?'digest':'getRandomValues',original=target[method].bind(target),spy=vi.spyOn(target,method).mockImplementation((...args)=>{const selected=phase==='read'?String(args[0]).startsWith('SELECT value FROM proof_operations'):phase==='write'?String(args[0]).startsWith('INSERT INTO proof_operations'):true;if(selected){hits++;throw new Error('proof_rejected PRIVATE');}return original(...args);});try{expect(await i.issue({action:'recover-key',keyId:f.keyId})).toEqual({ok:false,error:'service_unavailable'});expect(hits).toBe(1);}finally{spy.mockRestore();}});expect(await ops(s)).toEqual([]);expect(await row(s)).toBeUndefined();expect((await issue(s,f)).ok).toBe(true);});
for(const action of ['recover-key','delete-key','submit'])test('issue after-commit failure retains operation without invented idempotency: '+action,async()=>{const f=await software(),{s}=await setup(f,false),input={action,keyId:f.keyId,...(action==='submit'?{binding:binding()}:{})};await runInDurableObject(s,async(i,c)=>{let hits=0;const original=c.storage.transactionSync.bind(c.storage),spy=vi.spyOn(c.storage,'transactionSync').mockImplementation((...args)=>{original(...args);hits++;throw new Error('uncertain PRIVATE');});try{expect(await i.issue(input)).toEqual({ok:false,error:'service_unavailable'});expect(hits).toBe(1);}finally{spy.mockRestore();}});const saved=await ops(s);expect(saved).toHaveLength(1);const result=await s.issue(input);expect(result.ok).toBe(true);expect((await ops(s)).length).toBe(action==='submit'?2:1);if(action!=='submit'){expect(result.challenge_id).toBe(saved[0].id);expect(result.challenge).toBe(saved[0].nonce);expect(result.expires_at).toBe(saved[0].expiresAt);}else{expect(result.challenge_id).not.toBe(saved[0].id);expect(result.expires_at).toBe(input.binding.expiresAt);expect((await ops(s)).find(v=>v.id===saved[0].id)).toEqual(saved[0]);}});
for(const mode of ['expiry','rollback'])test('issue throwing alarm retains known requested window without SQL fallback: '+mode,async()=>{const f=await software(),{s}=await setup(f,false),at=Date.now();await clock(at,async()=>{await runInDurableObject(s,async(i,c)=>{let hits=0,reads=0;const exec=c.storage.sql.exec.bind(c.storage.sql),read=vi.spyOn(c.storage.sql,'exec').mockImplementation((...args)=>{reads++;return exec(...args);}),alarm=vi.spyOn(c.storage,'setAlarm').mockImplementation(()=>{hits++;vi.setSystemTime(mode==='expiry'?at+120000:at-1);throw new Error('PRIVATE');});try{expect(await i.issue({action:'recover-key',keyId:f.keyId})).toEqual({ok:false,error:'proof_rejected'});expect(hits).toBe(1);expect(reads).toBe(0);}finally{alarm.mockRestore();read.mockRestore();}});});expect(await ops(s)).toEqual([]);});
for(const value of [null,undefined,[],31,'invalid'])test('issue malformed input stays rejected: '+String(value),async()=>{const f=await software(),{s}=await setup(f,false);expect(await s.issue(value)).toEqual({ok:false,error:'proof_rejected'});expect(await ops(s)).toEqual([]);});
