for(const action of ['recover-key','delete-key','submit'])for(const phase of ['snapshot-read','transaction','digest','commit','arm-read','set-alarm','final-read']){
 if(action==='delete-key'&&phase==='final-read')continue;
 test('authorize internal fault has closed classification and original-state repair: '+action+'/'+phase,async()=>{
  const f=await software(),{s}=await setup(f),ch=await issue(s,f,action,action==='submit'?binding():undefined),request=await proof(f,ch,1,action),before=await ops(s);
  await runInDurableObject(s,async(i,c)=>{
   let hits=0,transactions=0,committed=false,armed=false;
   const target=phase==='digest'?crypto.subtle:phase==='transaction'||phase==='commit'||phase==='set-alarm'?c.storage:c.storage.sql;
   const method=phase==='digest'?'digest':phase==='transaction'||phase==='commit'?'transactionSync':phase==='set-alarm'?'setAlarm':'exec',original=target[method].bind(target);
   const spy=vi.spyOn(target,method).mockImplementation((...a)=>{
    const sql=String(a[0]);let selected=false;
    if(phase==='transaction')selected=true;
    if(phase==='digest')selected=true;
    if(phase==='commit'){transactions++;if(transactions===2){const result=original(...a);committed=true;hits++;throw new Error('PRIVATE proof_rejected');}return original(...a);}
    if(phase==='set-alarm')selected=true;
    if(phase==='snapshot-read')selected=sql.startsWith('SELECT value FROM proof_operations WHERE');
    if(phase==='arm-read')selected=sql.startsWith('SELECT MIN(expires_at)');
    if(phase==='final-read'){if(sql.startsWith('SELECT MIN(expires_at)'))armed=true;selected=armed&&sql.startsWith('SELECT value FROM proof_operations WHERE');}
    if(selected){hits++;throw new Error('PRIVATE proof_rejected');}return original(...a);
   });
   try{expect(await i.authorize(request)).toEqual({ok:false,error:'service_unavailable'});expect(hits).toBe(1);if(phase==='commit')expect(committed).toBe(true);}finally{spy.mockRestore();}
  });
  const postcommit=['commit','arm-read','set-alarm','final-read'].includes(phase),r=await row(s),saved=await ops(s);
  if(postcommit&&action==='delete-key'){expect(r.status).toBe('revoked');expect(saved).toEqual([]);expect(await s.authorize(request)).toEqual({ok:false,error:'proof_rejected'});expect((await row(s)).status).toBe('revoked');}
  else{expect(r.counter).toBe(postcommit?1:0);if(postcommit){expect(saved[0].status).toBe('authorized');expect(saved[0].expiresAt).toBe(before[0].expiresAt);}else expect(saved).toEqual(before);
   const result=await s.authorize(request);expect(result.ok).toBe(true);if(action!=='delete-key'){expect((await row(s)).counter).toBe(1);if(action==='submit'&&postcommit)expect(result.authorizationExpiresAt).toBe(saved[0].authorizationExpiresAt);}}
 });
}
